public long power(long x, int n) {
    if (n == 0) return 1;
    long half = power(x, n / 2);
    long sq = half * half;
    return (n % 2 == 0) ? sq : sq * x;
}

code.python:
def power(x: int, n: int) -> int:
    if n == 0:
        return 1
    half = power(x, n // 2)
    return half * half if n % 2 == 0 else half * half * x
